-- ESP32 Wi-Fi Weather Station (slug 23).
-- Adds the Adafruit BME280 and the two USB parts this project needs.
-- Does not modify BMP280, slug 4, other project BOMs, or existing reviews.
-- Leaves slug 23 unpublished.

do $$
begin
  if exists (
    select 1 from public.projects
    where slug = '23' and title <> 'ESP32 Wi-Fi Weather Station'
  ) then
    raise exception 'slug 23 already belongs to a different project';
  end if;
end;
$$;

insert into public.components (name, category, description, slug)
values
  ('Adafruit BME280', 'sensors', 'Temperature, humidity, and pressure breakout. I2C uses Vin, GND, SCK, and SDI.', 'bme280'),
  ('USB data cable', 'modules', 'Data-capable USB cable. Espressif ESP32-DevKitC V4 uses USB-A to Micro-B. The plug must match the DevKit socket.', 'usb-data-cable'),
  ('USB power source', 'power', 'Computer USB port or USB charger. Espressif ESP32-DevKitC V4 takes power from USB, or the 5V pin, or the 3V3 pin, and only one of those at a time.', 'usb-power-source')
on conflict (slug) do update
set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description;

insert into public.component_capabilities (component_id, capability, value)
select c.id, v.capability, v.value
from (
  values
    ('bme280', 'function', 'bme280'),
    ('bme280', 'interface', 'i2c'),
    ('bme280', 'interface', 'spi')
) as v(slug, capability, value)
join public.components c on c.slug = v.slug
on conflict (component_id, capability, value) do update
set value = excluded.value;

insert into public.projects (
  slug,
  title,
  description,
  overview,
  category,
  difficulty,
  duration_label,
  image_key,
  learning_objectives,
  sort_order,
  is_published
)
values (
  '23',
  'ESP32 Wi-Fi Weather Station',
  'Measure temperature, humidity, and pressure, then read them on a local ESP32 web page.',
  'Build a local weather station with an ESP32 DevKit and an Adafruit BME280. The board joins your Wi-Fi network and serves a dashboard that refreshes temperature, humidity, and pressure. No cloud account is required.',
  'iot',
  'intermediate',
  '3 hrs',
  'esp32WifiWeather',
  array['Wire an Adafruit BME280 to an ESP32 DevKit on I2C at 3.3 V', 'Install the ESP32 Arduino board package and the Adafruit BME280 library', 'Host a local web dashboard and JSON readings endpoint on the ESP32', 'Use the Serial Monitor to diagnose the sensor and the Wi-Fi address'],
  23,
  false
)
on conflict (slug) do update
set
  title = excluded.title,
  description = excluded.description,
  overview = excluded.overview,
  category = excluded.category,
  difficulty = excluded.difficulty,
  duration_label = excluded.duration_label,
  image_key = excluded.image_key,
  learning_objectives = excluded.learning_objectives,
  sort_order = excluded.sort_order,
  is_published = false;

delete from public.project_components
where project_id = (select id from public.projects where slug = '23');

insert into public.project_components (project_id, component_id, quantity, sort_order)
values
  ((select id from public.projects where slug = '23'), (select id from public.components where slug = 'esp32'), 1, 1),
  ((select id from public.projects where slug = '23'), (select id from public.components where slug = 'bme280'), 1, 2),
  ((select id from public.projects where slug = '23'), (select id from public.components where slug = 'breadboard'), 1, 3),
  ((select id from public.projects where slug = '23'), (select id from public.components where slug = 'jumper-wires'), 1, 4),
  ((select id from public.projects where slug = '23'), (select id from public.components where slug = 'usb-data-cable'), 1, 5),
  ((select id from public.projects where slug = '23'), (select id from public.components where slug = 'usb-power-source'), 1, 6);

insert into public.project_requirements (
  project_id,
  project_component_id,
  role,
  substitution_policy,
  sort_order
)
select
  p.id,
  pc.id,
  v.role,
  'exact',
  pc.sort_order
from public.projects p
join public.project_components pc on pc.project_id = p.id
join public.components c on c.id = pc.component_id
join (
  values
  ('esp32', 'microcontroller'),
  ('bme280', 'environment_sensor'),
  ('breadboard', 'breadboard'),
  ('jumper-wires', 'jumper_wires'),
  ('usb-data-cable', 'usb_cable'),
  ('usb-power-source', 'usb_power')
) as v(slug, role) on v.slug = c.slug
where p.slug = '23'
on conflict (project_component_id) do update
set
  role = excluded.role,
  substitution_policy = excluded.substitution_policy,
  sort_order = excluded.sort_order;

insert into public.project_requirement_constraints (requirement_id, capability, value)
select r.id, v.capability, v.value
from public.project_requirements r
join public.project_components pc on pc.id = r.project_component_id
join public.projects p on p.id = r.project_id
join public.components c on c.id = pc.component_id
join (
  values
    ('esp32', 'function', 'development_board'),
    ('esp32', 'logic_level_v', '3.3'),
    ('esp32', 'supply_v', '3.3'),
    ('esp32', 'programming_environment', 'arduino_ide'),
    ('esp32', 'board_package', 'esp32'),
    ('bme280', 'function', 'bme280'),
    ('bme280', 'interface', 'i2c')
) as v(slug, capability, value) on v.slug = c.slug
where p.slug = '23'
on conflict (requirement_id, capability, value) do update
set value = excluded.value;

delete from public.project_steps
where project_id = (select id from public.projects where slug = '23');

insert into public.project_steps (
  project_id,
  sort_order,
  stage_sort_order,
  stage_title,
  title,
  description,
  tip,
  blocks
)
select
  p.id,
  v.sort_order,
  v.stage_sort_order,
  v.stage_title,
  v.title,
  v.description,
  v.tip,
  v.blocks::jsonb
from public.projects p
cross join (
  values
  (0, 0, 'Introduction', 'What the finished station does', 'The ESP32 reads a BME280 and serves the readings on your own Wi-Fi network.', null, $wxsteps$[{"type":"image","imageKey":"esp32WifiWeather","caption":"ESP32, BME280, and a local dashboard. This drawing is the project cover, not a photograph of a finished build."},{"type":"text","heading":"What you are building","body":"The finished station measures temperature in degrees Celsius, relative humidity in percent, and barometric pressure in hectopascals. The ESP32 DevKit joins a Wi-Fi network you choose and hosts a small web page. A phone or computer on that same network opens the page and sees the numbers update about every two seconds. Nothing is sent to a cloud service."},{"type":"expected","heading":"What done looks like","body":"The Serial Monitor prints an IP address such as 192.168.1.42, then repeating temperature, humidity, and pressure lines. Opening http:// and that address in a browser shows the same three readings."}]$wxsteps$),
  (1, 0, 'Introduction', 'What you will learn', 'This build is about one sensor bus, one Wi-Fi connection, and one local web page.', null, $wxsteps$[{"type":"text","heading":"Skills in this project","body":"You will identify the ESP32 pins 3V3, GND, IO21, and IO22, and the Adafruit BME280 pins Vin, GND, SCK, and SDI. You will install the ESP32 board package and the Adafruit BME280 library, upload a complete sketch, and read both the Serial Monitor and a browser. You will also see how a failed sensor or a failed Wi-Fi join is reported instead of being hidden."},{"type":"text","heading":"What this project does not teach","body":"It does not use a BMP280. A BMP280 can report pressure and temperature, but it has no humidity measurement, and this dashboard needs humidity. It also does not use the ESP32-CAM, an ESP8266, or a Raspberry Pi. Those boards do not share this pin map."}]$wxsteps$),
  (2, 0, 'Introduction', 'How the hardware and software work together', 'Four wires carry power and I2C. The sketch turns those readings into a web page.', null, $wxsteps$[{"type":"text","heading":"The path of a reading","body":"USB power feeds the ESP32 DevKit. The board’s 3V3 pin feeds the BME280 Vin pin, and the two GND pins share a ground. IO21 is the I2C data line and goes to SDI. IO22 is the I2C clock and goes to SCK. The sketch asks the sensor at address 0x77 for temperature, humidity, and pressure, then stores the latest values. A browser requests the page at / and, every two seconds, the JSON document at /readings."},{"type":"text","heading":"Why the address is 0x77","body":"Adafruit’s BME280 guide says the default I2C address is 0x77 while SDO is left open. Connecting SDO to GND changes the address to 0x76. This project leaves SDO, CS, and 3Vo unconnected, so the sketch calls begin(0x77)."}]$wxsteps$),
  (3, 0, 'Introduction', 'What a successful build should do', 'Success is a local page with live units, plus a clear error when the sensor or Wi-Fi is missing.', null, $wxsteps$[{"type":"text","heading":"Check these behaviours","body":"After upload, the Serial Monitor at 115200 baud prints either “BME280 ready at 0x77.” or a not-found message. When Wi-Fi joins, it prints “Wi-Fi connected. IP address:” and the address. The web page shows temperature with C, humidity with %, and pressure with hPa. If the sensor is missing, the page shows the error text instead of fake numbers. If the browser is on another network, the page does not load."},{"type":"warning","body":"This repository has not run the sketch on a physical ESP32. Treat the Serial and browser results below as the behaviour the code is written to produce, and compare them with what your board actually prints."}]$wxsteps$),
  (4, 1, 'Hardware preparation', 'Identify every required component', 'Every physical item in this build is on the BOM. None of these six items is optional.', 'A phone or computer is how you view the page. It is not a wired component, so it is not a BOM line.', $wxsteps$[{"type":"components","heading":"Required parts","items":[{"id":"esp32","name":"ESP32 DevKit","illustrationId":"esp32","owned":false,"quantity":1},{"id":"bme280","name":"Adafruit BME280","illustrationId":"bme280","owned":false,"quantity":1},{"id":"breadboard","name":"Breadboard","illustrationId":"breadboard","owned":false,"quantity":1},{"id":"jumper-wires","name":"Jumper Wires","illustrationId":"jumper-wires","owned":false,"quantity":1},{"id":"usb-data-cable","name":"USB data cable","illustrationId":"usb-cable","owned":false,"quantity":1},{"id":"usb-power-source","name":"USB power source","illustrationId":"generic-module","owned":false,"quantity":1}]},{"type":"text","heading":"What each part is for","body":"The ESP32 DevKit is the controller and the web server. The Adafruit BME280 is the only sensor. The breadboard holds the sensor and the jumper wires. One pack of jumper wires makes the six electrical connections. The USB data cable carries power and the upload. The USB power source is the computer port while you program, or a USB charger after the sketch is on the board."},{"type":"expected","heading":"Check","body":"You can point to one ESP32 DevKit, one Adafruit BME280, one breadboard, one jumper pack, one data-capable USB cable, and a USB port or charger. A BMP280 board is not a substitute on this bench."}]$wxsteps$),
  (5, 1, 'Hardware preparation', 'Confirm the ESP32 DevKit labels', 'This guide uses the catalogue ESP32 DevKit only when its silkscreen matches the DevKitC labels used here.', 'Espressif’s ESP32-DevKitC V4 user guide lists a Micro-USB socket, a Boot button, and an EN button.', $wxsteps$[{"type":"text","heading":"What to look for","body":"Solderi’s ESP32 DevKit row is a 3.3 V board programmed with the Arduino-ESP32 package. This project’s wiring uses four header labels: 3V3, GND, IO21, and IO22. Espressif’s ESP32-DevKitC V4 breaks those names out on the headers: J2 starts with 3V3, and J3 includes IO22 and IO21. Arduino-ESP32’s generic ESP32 default I2C pins are GPIO21 for SDA and GPIO22 for SCL, which are those same headers."},{"type":"text","heading":"USB socket","body":"Espressif’s ESP32-DevKitC V4 uses a USB-A to Micro-B data cable, and its user guide says the Micro-USB port is the default power supply. The catalogue row does not record the socket on every board sold as a DevKit. Before you continue, confirm the silkscreen shows 3V3, GND, IO21 or GPIO21, and IO22 or GPIO22, and use a data cable that physically fits that socket. A charge-only cable can power the board and still never appear as a serial port."},{"type":"warning","body":"If your board does not show those four labels, stop. Do not move the wires to similarly numbered pins on an ESP32-CAM or another module. Espressif also warns that DevKitC V4 power must come from only one of USB, the 5V pin, or the 3V3 pin."}]$wxsteps$),
  (6, 1, 'Hardware preparation', 'Confirm the BME280 pin labels', 'Use the Adafruit breakout pin names, not a BMP280 module and not a clone with different silk.', 'Leave 3Vo, SDO, and CS empty for this project.', $wxsteps$[{"type":"text","heading":"Pins this project uses","body":"Adafruit’s BME280 pinout names Vin, 3Vo, GND, SCK, SDO, SDI, and CS. Vin is the power input and accepts 3–5 V. This project feeds Vin from the ESP32 3V3 pin. Adafruit says the logic level follows Vin, and the ESP32 DevKit’s GPIO is 3.3 V, so Vin must not be tied to 5 V. 3Vo is a 3.3 V output from the breakout’s regulator. Leave it unconnected. GND is the common ground."},{"type":"text","heading":"I2C pins and address","body":"SCK is the I2C clock and connects to IO22. SDI is the I2C data and connects to IO21. Adafruit’s I2C wiring uses those two signal pins plus Vin and GND, and says to leave the other pins disconnected. The default address is 0x77. A jumper from SDO to GND would select 0x76, which this sketch does not scan. Do not add pull-up resistors: Adafruit’s I2C wiring for this breakout does not call for extra resistors."},{"type":"expected","heading":"Check","body":"The board in your hand says BME280 and shows Vin, GND, SCK, and SDI. If the silk says BMP280, or the pins are labelled differently, this wiring table does not apply."}]$wxsteps$),
  (7, 1, 'Hardware preparation', 'Seat the board and the sensor', 'Put both boards on the breadboard while USB is still unplugged.', 'Straddle the ESP32 across the breadboard centre gap if the headers allow it. Do not bend the header pins to force a fit.', $wxsteps$[{"type":"text","heading":"What to do","body":"Press the ESP32 DevKit into the breadboard so 3V3, GND, IO21, and IO22 each have an empty hole in the same row. Press the BME280 in so Vin, GND, SCK, and SDI each have their own row. Keep the sensor away from the ESP32 antenna area. Leave the USB cable unplugged until the wiring check later in this guide."},{"type":"expected","heading":"What you should see","body":"Both boards sit flat. No pin is bent under a board. You can still read the silkscreen for 3V3, GND, IO21, IO22, Vin, GND, SCK, and SDI."}]$wxsteps$),
  (8, 2, 'Wiring', 'Connect power and ground', '3V3 and GND go to the breadboard rails, then from those rails to Vin and GND.', 'Use the breadboard’s red rail for 3V3 and the blue rail for ground. This project’s positive rail is 3.3 V, not 5 V.', $wxsteps$[{"type":"text","heading":"Connection sequence","body":"First jumper ESP32 3V3 to the breadboard + rail. Second, jumper ESP32 GND to the breadboard − rail. Third, jumper the + rail to BME280 Vin. Fourth, jumper the − rail to BME280 GND. Do not connect ESP32 5V. Do not connect BME280 3Vo. Do not connect SCK or SDI yet."},{"type":"wiring","heading":"Power and ground","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"3V3","toComponent":"Breadboard","toPin":"+ rail","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"+ rail","toComponent":"Adafruit BME280","toPin":"Vin","signal":"power"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Adafruit BME280","toPin":"GND","signal":"ground"}]},{"type":"connections","summary":"3V3 to Vin · GND to GND","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"3V3","toComponent":"Breadboard","toPin":"+ rail","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"+ rail","toComponent":"Adafruit BME280","toPin":"Vin","signal":"power"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Adafruit BME280","toPin":"GND","signal":"ground"}]},{"type":"warning","body":"Adafruit says BME280 logic follows the voltage on Vin. Five volts on Vin would present 5 V logic to IO21 and IO22. The ESP32 DevKit is a 3.3 V board. Keep Vin on 3V3."}]$wxsteps$),
  (9, 2, 'Wiring', 'Connect SDA and SCL', 'IO21 goes to SDI. IO22 goes to SCK. Those are the only signal wires.', 'SDA is data. SCL is clock. On this breakout the silk says SDI and SCK, not SDA and SCL.', $wxsteps$[{"type":"text","heading":"Connection sequence","body":"Jumper ESP32 IO21 to BME280 SDI. Jumper ESP32 IO22 to BME280 SCK. Leave SDO open so the address stays 0x77. Leave CS open. Adafruit’s I2C instructions do not add a separate pull-up resistor for this breakout."},{"type":"wiring","heading":"I2C signals","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"IO21","toComponent":"Adafruit BME280","toPin":"SDI","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO22","toComponent":"Adafruit BME280","toPin":"SCK","signal":"signal"}]},{"type":"connections","summary":"IO21 to SDI · IO22 to SCK","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"IO21","toComponent":"Adafruit BME280","toPin":"SDI","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO22","toComponent":"Adafruit BME280","toPin":"SCK","signal":"signal"}]},{"type":"expected","heading":"Check","body":"You can trace IO21 to SDI and IO22 to SCK without either wire sharing a breadboard row with 3V3 or GND."}]$wxsteps$),
  (10, 2, 'Wiring', 'Read the complete wiring table', 'These six connections are the whole circuit. The sketch uses the same GPIO numbers.', null, $wxsteps$[{"type":"wiring","heading":"Complete wiring diagram","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"3V3","toComponent":"Breadboard","toPin":"+ rail","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"+ rail","toComponent":"Adafruit BME280","toPin":"Vin","signal":"power"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Adafruit BME280","toPin":"GND","signal":"ground"},{"fromComponent":"ESP32 DevKit","fromPin":"IO21","toComponent":"Adafruit BME280","toPin":"SDI","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO22","toComponent":"Adafruit BME280","toPin":"SCK","signal":"signal"}]},{"type":"connections","heading":"Every electrical connection","summary":"IO21 SDA · IO22 SCL · 3V3 Vin · common GND · address 0x77","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"3V3","toComponent":"Breadboard","toPin":"+ rail","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"+ rail","toComponent":"Adafruit BME280","toPin":"Vin","signal":"power"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Adafruit BME280","toPin":"GND","signal":"ground"},{"fromComponent":"ESP32 DevKit","fromPin":"IO21","toComponent":"Adafruit BME280","toPin":"SDI","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO22","toComponent":"Adafruit BME280","toPin":"SCK","signal":"signal"}]},{"type":"text","heading":"How this matches the sketch","body":"The firmware sets I2C_SDA to 21 and I2C_SCL to 22, then calls Wire.begin(I2C_SDA, I2C_SCL) and bme.begin(0x77). GPIO21 is the header labelled IO21. GPIO22 is the header labelled IO22. There is no other GPIO in this project."}]$wxsteps$),
  (11, 2, 'Wiring', 'Check the circuit before you apply power', 'Look once more, then connect USB. Do not also feed the 5V or 3V3 header from a second supply.', 'Espressif’s DevKitC V4 guide says USB, the 5V pin, and the 3V3 pin are mutually exclusive power inputs.', $wxsteps$[{"type":"test","heading":"What to verify","body":"Count six jumpers. 3V3 reaches Vin and does not reach SCK, SDI, SDO, CS, or 3Vo. GND reaches BME280 GND. IO21 reaches only SDI. IO22 reaches only SCK. SDO and CS are empty. The USB cable is not yet plugged in, and nothing else is connected to the 5V pin."},{"type":"text","heading":"Then apply power","body":"Plug the data cable into the DevKit and into the computer USB port you will use for upload. On an ESP32-DevKitC V4, the 5V Power On LED lights when USB power is present. If you later move the board to a USB charger, unplug the computer first so only one power source is connected."},{"type":"expected","heading":"Expected result","body":"The board’s power LED is on. The sensor does not get hot. No sketch is running yet, so the Serial Monitor stays quiet until you upload."}]$wxsteps$),
  (12, 3, 'Development environment', 'Install the ESP32 board package', 'The Arduino IDE needs Espressif’s ESP32 package before this board appears in the Board menu.', 'Use the stable package URL. The development URL is a different, less settled package.', $wxsteps$[{"type":"text","heading":"What to do","body":"Install the current Arduino IDE from arduino.cc. Open File > Preferences, or Arduino IDE > Settings. In Additional boards manager URLs, add https://espressif.github.io/arduino-esp32/package_esp32_index.json and click OK. Open Tools > Board > Boards Manager, search for esp32 by Espressif Systems, and install the esp32 platform. Restart the IDE if the new board list does not appear."},{"type":"text","heading":"Why this package","body":"WiFi.h and WebServer.h come from that ESP32 package. They are not separate Library Manager installs. The generic ESP32 I2C defaults in that package are GPIO21 and GPIO22, which is why the sketch still names those pins explicitly."},{"type":"expected","heading":"What you should see","body":"Boards Manager shows the esp32 package as installed. Tools > Board contains an ESP32 Arduino group."}]$wxsteps$),
  (13, 3, 'Development environment', 'Select the board and the serial port', 'Choose ESP32 Dev Module, then the port that appears when the data cable is plugged in.', 'If the port never appears, try another cable before you change any wiring.', $wxsteps$[{"type":"text","heading":"Board","body":"Open Tools > Board > ESP32 Arduino and choose ESP32 Dev Module. That is the generic ESP32 target for this DevKit. Do not choose ESP32-CAM or an S2, S3, or C3 board. Leave the other Tools menu flash settings at the ESP32 Dev Module defaults unless a later upload error tells you to change one."},{"type":"text","heading":"Port","body":"Plug in the data cable. Open Tools > Port and select the new port. On Windows it is a COM port. On macOS it is a /dev/cu.usbserial or /dev/cu.SLAB port. Unplug the cable and open the menu again: the correct port is the one that disappears. Select it again after you plug the cable back in."},{"type":"troubleshooting","heading":"If the port is missing","items":[{"problem":"No new port appears","solution":"The cable may be charge-only, or it may be in the wrong socket. Use a data cable that fits the DevKit. Then reopen Tools > Port."},{"problem":"Several ports are listed","solution":"Unplug the DevKit, see which port vanishes, and select that one after reconnecting."}]}]$wxsteps$),
  (14, 3, 'Development environment', 'Install the BME280 libraries', 'Library Manager installs Adafruit BME280 Library together with its two dependencies.', 'Search for the library name Adafruit BME280 Library. Do not install a BMP280-only library in its place.', $wxsteps$[{"type":"text","heading":"What to install","body":"Open Tools > Manage Libraries. Search for Adafruit BME280 Library and install it. Its library.properties file depends on Adafruit Unified Sensor and Adafruit BusIO. Accept the prompt to install those dependencies if the IDE offers it. If it does not, install both by those names from Library Manager as well."},{"type":"text","heading":"What you do not install","body":"Do not install a separate Wi-Fi or web-server library. WiFi.h and WebServer.h are part of the ESP32 board package from the previous step. Do not install Adafruit BMP280 Library for this sketch. The include line is Adafruit_BME280.h, and begin() is the BME280 call."},{"type":"expected","heading":"Check","body":"Library Manager shows Adafruit BME280 Library, Adafruit Unified Sensor, and Adafruit BusIO as installed."}]$wxsteps$),
  (15, 3, 'Development environment', 'Set the Serial Monitor to 115200 baud', 'The sketch calls Serial.begin(115200). A mismatched baud rate looks like garbage text, not a dead board.', null, $wxsteps$[{"type":"text","heading":"What to do","body":"Open Tools > Serial Monitor. In the baud menu at the corner of the monitor, choose 115200. Leave the line ending on Newline. You will not see the weather lines until the sketch is uploaded, but setting the speed now avoids mistaking baud noise for a failed sensor."},{"type":"expected","heading":"What you should observe","body":"The monitor is open on the same port you selected for upload, and the baud value reads 115200. If you later see repeated characters that are not words, the baud setting has been changed."}]$wxsteps$),
  (16, 4, 'Firmware', 'Create the sketch and set the Wi-Fi name', 'Replace the two placeholders with your network name and password. Do not commit a real password into a shared copy.', 'The network must be 2.4 GHz. The ESP32 DevKit radio in this project does not join a 5 GHz-only network.', $wxsteps$[{"type":"text","heading":"What to do","body":"Create a sketch named esp32_wifi_weather_station. You will paste the complete program in a later step. The only lines you edit are the two Wi-Fi placeholders. Use the SSID and password of the same network your phone or computer will use to open the dashboard."},{"type":"code","language":"Arduino","filename":"esp32_wifi_weather_station.ino","libraries":["WiFi (ESP32 Arduino core)","WebServer (ESP32 Arduino core)","Wire (Arduino core)","Adafruit Unified Sensor","Adafruit BusIO","Adafruit BME280 Library"],"code":"const char *WIFI_SSID = \"YOUR_WIFI_NAME\";\nconst char *WIFI_PASSWORD = \"YOUR_WIFI_PASSWORD\";"},{"type":"code_explanation","heading":"Why these constants","body":"WIFI_SSID and WIFI_PASSWORD are ordinary C strings. YOUR_WIFI_NAME and YOUR_WIFI_PASSWORD are placeholders, not a working network. The rest of the sketch reads these two names, so you do not type the password anywhere else."}]$wxsteps$),
  (17, 4, 'Firmware', 'Start I2C and the BME280', 'The sketch opens GPIO21 and GPIO22, then looks for address 0x77.', null, $wxsteps$[{"type":"text","heading":"What this code does","body":"Wire.begin(21, 22) starts the hardware I2C peripheral on the same pins as the wiring table. bme.begin(0x77) asks the Adafruit library, version that provides begin(uint8_t addr), to initialise the sensor on that address. A true result means the chip answered. A false result is stored as an error and printed. The web server still starts, so the dashboard can show that error."},{"type":"code","language":"Arduino","filename":"esp32_wifi_weather_station.ino","libraries":["Wire","Adafruit BME280 Library","Adafruit Unified Sensor","Adafruit BusIO"],"code":"Wire.begin(I2C_SDA, I2C_SCL);\n  sensorReady = bme.begin(BME280_I2C_ADDRESS);"},{"type":"code_explanation","body":"readTemperature() returns degrees Celsius, readHumidity() returns percent, and readPressure() returns pascals as a float in the current Adafruit_BME280.h. The sketch divides pascals by 100 to show hectopascals. A NaN value becomes the invalid-reading error instead of a number on the page."}]$wxsteps$),
  (18, 4, 'Firmware', 'Serve the page and the JSON endpoint', 'The ESP32 answers / with HTML and /readings with the latest measurements.', 'The page asks /readings every two seconds. You do not refresh the browser by hand.', $wxsteps$[{"type":"text","heading":"What this code does","body":"WebServer server(80) listens on the normal web port. server.on registers two GET routes. handleRoot sends the dashboard HTML. handleReadings sends JSON fields ok, temperature_c, humidity_percent, pressure_hpa, wifi_connected, ip, and error. The HTML uses fetch(\"/readings\") and setInterval(..., 2000). It does not load fonts or scripts from the internet."},{"type":"code","language":"Arduino","filename":"esp32_wifi_weather_station.ino","libraries":["WebServer (ESP32 Arduino core)"],"code":"server.on(\"/\", HTTP_GET, handleRoot);\n  server.on(\"/readings\", HTTP_GET, handleReadings);\n  server.begin();"},{"type":"code_explanation","body":"loop() calls server.handleClient() every pass so the page stays responsive. Wi-Fi retries are timed with millis() and WIFI_RETRY_MS. There is no while-loop waiting forever for a network. If the join drops, the next retry prints “Connecting to Wi-Fi...” and the page’s status line says Wi-Fi disconnected until the address returns."}]$wxsteps$),
  (19, 4, 'Firmware', 'Paste the complete sketch and upload it', 'The program below is the whole firmware. Upload it with the board and port you already selected.', 'If the upload times out, hold the Boot button, press and release EN, then release Boot and try again. That is the DevKitC V4 download-mode sequence.', $wxsteps$[{"type":"code","language":"Arduino","filename":"esp32_wifi_weather_station.ino","libraries":["WiFi (ESP32 Arduino core)","WebServer (ESP32 Arduino core)","Wire (Arduino core)","Adafruit Unified Sensor","Adafruit BusIO","Adafruit BME280 Library"],"code":"/*\n * ESP32 Wi-Fi Weather Station\n * Board: ESP32 Dev Module\n * Sensor: Adafruit BME280 over I2C at 0x77\n * IO21 = SDA = BME280 SDI\n * IO22 = SCL = BME280 SCK\n * 3V3 = BME280 Vin\n * GND = BME280 GND\n */\n\n#include <WiFi.h>\n#include <WebServer.h>\n#include <Wire.h>\n#include <Adafruit_Sensor.h>\n#include <Adafruit_BME280.h>\n\nconst char *WIFI_SSID = \"YOUR_WIFI_NAME\";\nconst char *WIFI_PASSWORD = \"YOUR_WIFI_PASSWORD\";\n\nconst int I2C_SDA = 21;\nconst int I2C_SCL = 22;\nconst uint8_t BME280_I2C_ADDRESS = 0x77;\n\nconst unsigned long SENSOR_INTERVAL_MS = 2000;\nconst unsigned long WIFI_RETRY_MS = 5000;\n\nAdafruit_BME280 bme;\nWebServer server(80);\n\nbool sensorReady = false;\nString sensorError = \"Sensor has not been read yet.\";\nfloat temperatureC = NAN;\nfloat humidityPercent = NAN;\nfloat pressureHpa = NAN;\nunsigned long lastSensorReadMs = 0;\nunsigned long lastWifiAttemptMs = 0;\nbool wifiWasConnected = false;\n\nbool readingIsValid(float value) {\n  return !isnan(value);\n}\n\nvoid readSensor() {\n  if (!sensorReady) {\n    sensorError = \"BME280 was not found at address 0x77.\";\n    temperatureC = NAN;\n    humidityPercent = NAN;\n    pressureHpa = NAN;\n    return;\n  }\n\n  float nextTemperature = bme.readTemperature();\n  float nextHumidity = bme.readHumidity();\n  float nextPressurePa = bme.readPressure();\n\n  if (!readingIsValid(nextTemperature) || !readingIsValid(nextHumidity) || !readingIsValid(nextPressurePa)) {\n    sensorError = \"BME280 returned an invalid reading.\";\n    temperatureC = NAN;\n    humidityPercent = NAN;\n    pressureHpa = NAN;\n    return;\n  }\n\n  temperatureC = nextTemperature;\n  humidityPercent = nextHumidity;\n  pressureHpa = nextPressurePa / 100.0f;\n  sensorError = \"\";\n}\n\nvoid connectWifi() {\n  if (WiFi.status() == WL_CONNECTED) {\n    return;\n  }\n\n  unsigned long now = millis();\n  if (lastWifiAttemptMs != 0 && now - lastWifiAttemptMs < WIFI_RETRY_MS) {\n    return;\n  }\n\n  lastWifiAttemptMs = now;\n  Serial.println(\"Connecting to Wi-Fi...\");\n  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);\n}\n\nString jsonNumber(float value) {\n  if (!readingIsValid(value)) {\n    return \"null\";\n  }\n  return String(value, 2);\n}\n\nString readingsJson() {\n  bool wifiConnected = WiFi.status() == WL_CONNECTED;\n  String json = \"{\";\n  json += \"\\\"ok\\\":\";\n  json += sensorError.length() == 0 ? \"true\" : \"false\";\n  json += \",\\\"temperature_c\\\":\";\n  json += jsonNumber(temperatureC);\n  json += \",\\\"humidity_percent\\\":\";\n  json += jsonNumber(humidityPercent);\n  json += \",\\\"pressure_hpa\\\":\";\n  json += jsonNumber(pressureHpa);\n  json += \",\\\"wifi_connected\\\":\";\n  json += wifiConnected ? \"true\" : \"false\";\n  json += \",\\\"ip\\\":\\\"\";\n  json += wifiConnected ? WiFi.localIP().toString() : \"\";\n  json += \"\\\",\\\"error\\\":\\\"\";\n  json += sensorError;\n  json += \"\\\"}\";\n  return json;\n}\n\nconst char DASHBOARD_PAGE[] PROGMEM = R\"HTML(<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>ESP32 Weather</title>\n<style>\nbody{margin:0;background:#0f172a;color:#e2e8f0;font-family:sans-serif}\nmain{max-width:28rem;margin:0 auto;padding:1.25rem}\nh1{font-size:1.35rem}\n.grid{display:grid;gap:.75rem}\n.card{background:#1e293b;border-radius:12px;padding:1rem}\n.label{color:#94a3b8;font-size:.85rem}\n.value{font-size:2rem;margin-top:.25rem}\n.error{background:#7f1d1d;border-radius:12px;padding:.75rem 1rem}\n</style>\n</head>\n<body>\n<main>\n<h1>ESP32 Wi-Fi Weather Station</h1>\n<p id=\"status\">Waiting for readings.</p>\n<p id=\"error\" class=\"error\" hidden></p>\n<div class=\"grid\">\n<section class=\"card\"><div class=\"label\">Temperature</div><div id=\"temperature\" class=\"value\">-</div></section>\n<section class=\"card\"><div class=\"label\">Humidity</div><div id=\"humidity\" class=\"value\">-</div></section>\n<section class=\"card\"><div class=\"label\">Pressure</div><div id=\"pressure\" class=\"value\">-</div></section>\n</div>\n</main>\n<script>\nfunction show(id, text){document.getElementById(id).textContent = text;}\nasync function refresh(){\n  var status = document.getElementById(\"status\");\n  var error = document.getElementById(\"error\");\n  try {\n    var response = await fetch(\"/readings\");\n    if (!response.ok) { throw new Error(\"request failed\"); }\n    var data = await response.json();\n    status.textContent = data.wifi_connected ? \"Connected at \" + data.ip : \"Wi-Fi disconnected\";\n    if (data.ok) {\n      error.hidden = true;\n      show(\"temperature\", Number(data.temperature_c).toFixed(1) + \" C\");\n      show(\"humidity\", Number(data.humidity_percent).toFixed(1) + \" %\");\n      show(\"pressure\", Number(data.pressure_hpa).toFixed(1) + \" hPa\");\n    } else {\n      error.hidden = false;\n      error.textContent = data.error || \"Sensor reading unavailable\";\n      show(\"temperature\", \"-\");\n      show(\"humidity\", \"-\");\n      show(\"pressure\", \"-\");\n    }\n  } catch (err) {\n    status.textContent = \"Dashboard not updating\";\n    error.hidden = false;\n    error.textContent = \"This browser could not read /readings. Use the ESP32 IP on the same Wi-Fi network.\";\n  }\n}\nrefresh();\nsetInterval(refresh, 2000);\n</script>\n</body>\n</html>)HTML\";\n\nvoid handleRoot() {\n  server.send(200, \"text/html\", DASHBOARD_PAGE);\n}\n\nvoid handleReadings() {\n  server.send(200, \"application/json\", readingsJson());\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(500);\n  Serial.println();\n  Serial.println(\"ESP32 Wi-Fi weather station\");\n\n  Wire.begin(I2C_SDA, I2C_SCL);\n  sensorReady = bme.begin(BME280_I2C_ADDRESS);\n  if (sensorReady) {\n    Serial.println(\"BME280 ready at 0x77.\");\n  } else {\n    sensorError = \"BME280 was not found at address 0x77.\";\n    Serial.println(sensorError);\n    Serial.println(\"Leave SDO unconnected for 0x77. A wire from SDO to GND selects 0x76, which this sketch does not use.\");\n  }\n\n  WiFi.mode(WIFI_STA);\n  connectWifi();\n\n  server.on(\"/\", HTTP_GET, handleRoot);\n  server.on(\"/readings\", HTTP_GET, handleReadings);\n  server.begin();\n  Serial.println(\"HTTP server started on port 80.\");\n}\n\nvoid loop() {\n  bool wifiConnected = WiFi.status() == WL_CONNECTED;\n  if (!wifiConnected) {\n    wifiWasConnected = false;\n    connectWifi();\n  } else if (!wifiWasConnected) {\n    wifiWasConnected = true;\n    Serial.print(\"Wi-Fi connected. IP address: \");\n    Serial.println(WiFi.localIP());\n  }\n\n  server.handleClient();\n\n  unsigned long now = millis();\n  if (now - lastSensorReadMs >= SENSOR_INTERVAL_MS) {\n    lastSensorReadMs = now;\n    readSensor();\n    if (sensorError.length() == 0) {\n      Serial.print(\"Temperature C: \");\n      Serial.print(temperatureC, 1);\n      Serial.print(\"  Humidity %: \");\n      Serial.print(humidityPercent, 1);\n      Serial.print(\"  Pressure hPa: \");\n      Serial.println(pressureHpa, 1);\n    } else {\n      Serial.println(sensorError);\n    }\n  }\n}\n"},{"type":"text","heading":"Upload","body":"Replace the two Wi-Fi placeholders if you have not already. Click Upload. Wait until the IDE prints “Hard resetting via RTS pin...” or the equivalent done message. Then open the Serial Monitor at 115200 baud. Do not change IO21, IO22, or 0x77 unless you also change the wiring."},{"type":"expected","heading":"What you should observe","body":"The IDE finishes the upload without a port error. The Serial Monitor then prints “ESP32 Wi-Fi weather station” and either the sensor-ready line or the not-found line."}]$wxsteps$),
  (20, 5, 'First run', 'Read the Serial Monitor', 'The first lines tell you whether the sensor answered and whether Wi-Fi has been attempted.', null, $wxsteps$[{"type":"text","heading":"What to do","body":"Leave the USB cable on the computer. Open Tools > Serial Monitor at 115200 baud. Press the EN button once if you want a clean restart. Watch the first five seconds."},{"type":"expected","heading":"A healthy start","body":"You should see “ESP32 Wi-Fi weather station”, then “BME280 ready at 0x77.”, then “Connecting to Wi-Fi...”, then “HTTP server started on port 80.” When the network accepts the board, the next line is “Wi-Fi connected. IP address:” followed by a number. After that, temperature, humidity, and pressure print about every two seconds."},{"type":"troubleshooting","heading":"If the text is wrong","items":[{"problem":"The monitor shows symbols instead of words","solution":"Set the baud rate to 115200. The sketch does not use 9600."},{"problem":"Nothing is printed","solution":"Confirm the port is the DevKit port and that the upload finished. Press EN once."}]}]$wxsteps$),
  (21, 5, 'First run', 'Find the ESP32 IP address', 'The address is printed only after Wi-Fi connects. The dashboard uses that address.', 'Write the address down. It can change if the router hands out a new lease later.', $wxsteps$[{"type":"text","heading":"What to look for","body":"Find the line “Wi-Fi connected. IP address:”. The four numbers after it, such as 192.168.1.42, are the local address. The sketch also puts that address in the JSON field ip. If the monitor keeps printing “Connecting to Wi-Fi...” every five seconds, the join has not succeeded and there is no page to open yet."},{"type":"expected","heading":"Expected result","body":"One IPv4 address is printed, and it stays stable across the next sensor lines. You will type http:// and that address into a browser on the same network."}]$wxsteps$),
  (22, 5, 'First run', 'Confirm the sensor readings', 'Temperature, humidity, and pressure should be plausible for the room before you trust the web page.', 'Breathing gently across the sensor should move humidity. Do not cover the board so tightly that it overheats.', $wxsteps$[{"type":"text","heading":"What to do","body":"Read several Serial lines. Temperature is printed in C, humidity in %, and pressure in hPa. Compare the temperature with the room and the pressure with a local weather report. The report will not match to the last digit; it should be in the same neighbourhood, often near 1000 hPa at low altitude. Then breathe across the sensor and watch humidity."},{"type":"expected","heading":"Expected result","body":"The three numbers keep updating. Humidity moves when you breathe on the sensor. Temperature does not jump by tens of degrees. If the monitor says “BME280 returned an invalid reading.” or the not-found message, fix the sensor before opening the dashboard."}]$wxsteps$),
  (23, 6, 'Dashboard', 'Open the web interface', 'Use the IP address from the Serial Monitor. Do not search for the board on the public internet.', 'Include http:// if the browser tries to search for the numbers instead of opening them.', $wxsteps$[{"type":"text","heading":"What to do","body":"On a phone or computer joined to the same Wi-Fi network, open a browser to http:// and the IP address from the Serial Monitor. The ESP32 returns the dashboard for /. Leave that tab open."},{"type":"expected","heading":"What you should see","body":"The title is “ESP32 Wi-Fi Weather Station”. A status line says “Connected at” and the IP address. Three cards show temperature, humidity, and pressure. The values change without a manual reload. If the sensor failed, a red error box shows the same message as the Serial Monitor and the cards show a dash."}]$wxsteps$),
  (24, 6, 'Dashboard', 'Understand each measurement', 'The page uses the same units as the Serial Monitor.', null, $wxsteps$[{"type":"text","heading":"The three cards","body":"Temperature is degrees Celsius from readTemperature(). Humidity is relative humidity in percent from readHumidity(). Pressure is hectopascals, which is the library’s pascal reading divided by 100. The status line is the Wi-Fi state, not a weather forecast. There is no outdoor temperature, rainfall, or wind in this project."},{"type":"text","heading":"Automatic updates","body":"The page calls /readings every 2000 ms, which is the same SENSOR_INTERVAL_MS the sketch uses to take a new sample. You should see the numbers change, or the error box appear, without pressing reload. You can also open http://THE_IP/readings directly to see the JSON document the page is using."}]$wxsteps$),
  (25, 6, 'Dashboard', 'Use the page on a phone and a computer', 'Any browser on the same local network can open the station. A device on mobile data cannot.', 'If the phone is on cellular data, join the same Wi-Fi network as the ESP32 first.', $wxsteps$[{"type":"text","heading":"What to do","body":"Open the same http://IP address on a second device. The page layout is a single column with large type so it fits a phone width. Both devices should show the same reading within one refresh. Unplug the Wi-Fi router only if you are ready to watch the status change to Wi-Fi disconnected; otherwise leave the network up."},{"type":"expected","heading":"Expected result","body":"Both browsers show the dashboard. The status line includes the IP address while Wi-Fi is connected. Closing the Serial Monitor does not stop the page, because the page is served by the ESP32, not by the Arduino IDE."}]$wxsteps$),
  (26, 7, 'Troubleshooting', 'The ESP32 is not detected or the upload fails', 'Fix the cable, the port, and the boot button before you change the circuit.', null, $wxsteps$[{"type":"troubleshooting","heading":"Board and upload","items":[{"problem":"The ESP32 never appears as a port","solution":"Use a data-capable cable that fits the socket. Plug it directly into the computer, select Tools > Port again, and confirm the power LED is on. A charge-only cable can light the LED and still provide no serial port."},{"problem":"Upload times out or cannot connect","solution":"Confirm the board is ESP32 Dev Module and the port is the one that disappears when you unplug the cable. Hold Boot, tap EN, release Boot, and upload again. That is the DevKitC V4 firmware-download sequence."},{"problem":"The IDE cannot find WiFi.h or WebServer.h","solution":"The ESP32 board package is not selected or not installed. Install the esp32 package from the stable Espressif boards URL and choose ESP32 Dev Module."}]}]$wxsteps$),
  (27, 7, 'Troubleshooting', 'The sensor, Wi-Fi, or dashboard fails', 'The Serial line names the fault. Match it to the wiring or the network before rewriting the sketch.', 'Adafruit notes that intermittent I2C on the original non-STEMMA BME280 can be improved by jumpering CS to Vin. Try that only after the four main wires are correct.', $wxsteps$[{"type":"troubleshooting","heading":"Sensor, network, and page","items":[{"problem":"Serial says the BME280 was not found at 0x77","solution":"Check Vin on 3V3, GND on GND, SDI on IO21, and SCK on IO22. Leave SDO open. A wire from SDO to GND selects 0x76, and this sketch will not find that address. Confirm the board is a BME280, not a BMP280."},{"problem":"Serial says the BME280 returned an invalid reading","solution":"Power and ground are probably present because the chip answered begin(), but a later read failed. Reseat SCK and SDI, keep the wires short, and press EN to restart."},{"problem":"The monitor repeats “Connecting to Wi-Fi...”","solution":"Check the SSID and password, including capitals. The DevKit needs a 2.4 GHz network. The computer’s serial cable does not join Wi-Fi for the board; the board joins by itself."},{"problem":"The browser cannot open the IP address","solution":"Use http:// and the address from the latest “Wi-Fi connected” line. The phone or computer must be on that same network. Another network, or mobile data, cannot route to the ESP32."},{"problem":"The page stays on “Dashboard not updating”","solution":"The HTML loaded, but /readings did not. Reload once. If Serial has stopped printing, press EN. If Serial is printing and the page still fails, confirm you opened the ESP32 address and not a cached page from another device."}]}]$wxsteps$),
  (28, 8, 'Understanding and extending the project', 'How this I2C link works', 'Two wires and one address are enough because the ESP32 is the only master.', null, $wxsteps$[{"type":"text","heading":"Clock and data","body":"I2C uses SCL for the clock and SDA for the data. On this board those pins are IO22 and IO21. The ESP32 generates the clock and talks to the address in bme.begin. The BME280 does not send readings until that address is used. Arduino-ESP32 documents that SDA and SCL need pull-ups; this project relies on the Adafruit breakout’s I2C wiring, which connects SCK and SDI without extra resistors."},{"type":"text","heading":"Why BMP280 is a different part","body":"The BME280 measures humidity as well as pressure and temperature. A BMP280 does not provide that humidity reading, so it cannot fill this dashboard even if it shares a similar package. Solderi keeps the two parts as different catalogue rows, and this project does not approve the BMP280 as a substitute."}]$wxsteps$),
  (29, 8, 'Understanding and extending the project', 'How the ESP32 hosts the page', 'The board is a small web server on your LAN. Your browser is the client.', null, $wxsteps$[{"type":"text","heading":"Address and routes","body":"After WiFi.begin succeeds, the router gives the ESP32 an address. server.begin() listens on port 80. A browser request for / receives the HTML. The script inside that HTML requests /readings. handleReadings sends the latest sample as JSON. The sketch updates that sample on SENSOR_INTERVAL_MS without waiting inside a blocking Wi-Fi loop."},{"type":"text","heading":"What is deliberately absent","body":"There is no API key, no account, and no external weather service. If your internet connection drops but the local Wi-Fi router stays up, the page can still load. If the ESP32 itself drops off Wi-Fi, the status line changes and connectWifi() tries again every five seconds."}]$wxsteps$),
  (30, 8, 'Understanding and extending the project', 'Ideas that are not part of this build', 'These extensions need their own wiring or code review. They are not already supported.', null, $wxsteps$[{"type":"text","heading":"Possible later work","body":"A second sensor, an outdoor enclosure, a display, or a cloud upload would change the BOM, the power budget, or the firmware. Switching SDO to ground would require changing BME280_I2C_ADDRESS to 0x76 and saying so in the wiring steps. None of that is included here. The working station is the six-wire circuit, the sketch you uploaded, and the local dashboard."},{"type":"expected","heading":"What you have now","body":"An ESP32 DevKit reads an Adafruit BME280 at 0x77 on IO21 and IO22, joins your Wi-Fi, and shows temperature, humidity, and pressure in a browser on the same network."}]$wxsteps$)
) as v(sort_order, stage_sort_order, stage_title, title, description, tip, blocks)
where p.slug = '23';
